const fs = require("fs");
const join = require("path").join;
const express = require("express");
const mongoose = require("mongoose");
const config = require("./config.js");
const cors = require("cors");
const app = express();
const io = require("socket.io")();

// require all models.
const models = join(__dirname, "app/models");
fs.readdirSync(models)
  .filter((file) => ~file.search(/^[^.].*\.js$/))
  .forEach((file) => require(join(models, file)));

app.use(express.urlencoded({ extended: true }));
app.use(express.json());
app.use(
  cors({
    optionsSuccessStatus: 200, // some legacy browsers (IE11, various SmartTVs) choke on 204
    credentials: true,
  })
);
app.use(config.staticPath, express.static("uploads"));
app.use(express.static(__dirname + "/public"));
require("./app/routes/routes.js")(app);
require("./app/socket/socket.js")(io);

app.use(express.static("public"));
app.get("/", function (req, res, next) {
  let aaa = join(
    __dirname,
    "/public/coreui-free-bootstrap-admin-template/dist/index.html"
  );
  res.sendFile(aaa);
});

connectMongoDB();

function connectMongoDB() {
  console.log(config.dbString);
  mongoose.connection
    .on("error", console.log)
    .on("disconnected", connectMongoDB)
    .once("open", startServer);
  console.log("before connect");
  return mongoose.connect(config.dbString, {
    keepAlive: 1,
    useNewUrlParser: true,
    useUnifiedTopology: true,
    useCreateIndex: true,
    useFindAndModify: false,
  });
}

function startServer() {
  app.listen(config.serverPort, () => console.log("Server is running"));
  io.listen(config.socketPort, () => console.log("Socket is running"));

  checkFolders();
}

function checkFolders() {
  if (!fs.existsSync(config.originalDirectory)) {
    fs.mkdirSync(config.originalDirectory, { recursive: true });
  }

  if (!fs.existsSync(config.originalThumbnailDirectory)) {
    fs.mkdirSync(config.originalThumbnailDirectory);
  }

  if (!fs.existsSync(config.effectDirectory)) {
    fs.mkdirSync(config.effectDirectory, { recursive: true });
  }

  if (!fs.existsSync(config.effectThumbnailDirectory)) {
    fs.mkdirSync(config.effectThumbnailDirectory);
  }

  if (!fs.existsSync(config.frameDirectory)) {
    fs.mkdirSync(config.frameDirectory);
  }

  if (!fs.existsSync(config.audioDirectory)) {
    fs.mkdirSync(config.audioDirectory);
  }

  if (!fs.existsSync(config.resultDirectory)) {
    fs.mkdirSync(config.resultDirectory);
  }
}

exports.io = io;

