const mongoose   = require('mongoose');
const formidable = require('formidable');
const elapsed    = require('elapsed-time');
const path       = require('path');
const fs         = require('fs');

const ffmpeg     = require('../utils/ffmpeg.js');
const config     = require('../../config.js');

const File = mongoose.model('File');

exports.upload = async function (req, res) {
    const et = elapsed.new().start();
    const promises = [];
    const error = [];
    var counter = 0;

    new formidable.IncomingForm({
        hash: 'md5',
        maxFileSize: 2000 * 1024 * 1024,
        keepExtensions: true,
        multiples: true,
    })
        .on('fileBegin', function(filename, file) {
            var mime = file.type;
            switch (mime) {
                case 'video/webm':
                    file.path = path.join(config.effectDirectory, file.name);
                    break;
                case 'image/png':
                    file.path = path.join(config.frameDirectory, file.name);
                    break;
                case 'audio/ogg':
                    file.path = path.join(config.audioDirectory, file.name);
                    break;
                default:
                    break;
            }
        })
        .on('file', async function (name, file) {
            // console.log('Uploaded: ' + file.name + ' - elapsed time: ' + et.getValue());
            var mime = file.type;
            switch (mime) {
                case 'video/webm':
                    var fileName = file.name.split('.').slice(0, -1).join('.');
                    var inputFile = path.join(config.effectDirectory, file.name);

                    et.reset();
                    et.start();

                    promises
                        .push(new File().addFile(file, 'effect', req.protocol + '://' + req.get('host') + config.staticPath).then(
                            function (doc) {
                                counter += 1;
                                ffmpeg.thumbnail(fileName, inputFile, config.effectThumbnailDirectory,
                                    (data) => {
                                        doc.addThumbnail(path.join(config.effectThumbnailDirectory, fileName + '.png'), req.protocol + '://' + req.get('host') + config.staticPath);
                                        console.log('Success extract thumbnail: ' + file.name + ' - elapsed time: ' + et.getValue()) 
                                    },
                                    (data) => { error.push('fail extract thumbnail'); console.log('Fail extract thumbnail: ' + file.name + ' - error: ' + data) });
                            },
                            function (err) {
                                error.push(err.errmsg);
                            }
                        )
                    );
                    break;
                case 'image/png':
                    promises
                        .push(new File().addFile(file, 'frame', req.protocol + '://' + req.get('host') + config.staticPath)
                        .then(
                            function () { counter += 1; },
                            function (err) { error.push(err.errmsg); }
                        )
                    );
                    break;
                case 'audio/ogg':
                    promises
                        .push(new File().addFile(file, 'audio', req.protocol + '://' + req.get('host') + config.staticPath)
                        .then(
                            function () { counter += 1; },
                            function (err) { error.push(err.errmsg); }
                        )
                    );
                    break;
                default:
                    break;
            }
        })
        .on('aborted', () => { console.log('aborted'); })
        .on('error', (err) => { console.log(err); res.sendStatus(400); return; })
        .on('end', () => { Promise.all(promises).then(
            (values) => {
                res.status(200).send({
                    code: 200,
                    status: 'success',
                    message: counter + ' file(s) uploaded.',
                    error: error
                })
            },
            (err) => {
                res.status(400).send({
                    code: 400,
                    status: 'error',
                    error: err
                }
            )}
        )})
        .parse(req);
}

