const mongoose = require("mongoose");
const path = require("path");
const url = require("url");
const md5 = require("md5-file");
const fs = require("fs");
const fileUtils = require("../utils/fileUtils");

const DataSchema = new mongoose.Schema({
  original: { type: String, unique: true, required: true },
  effect: { type: String },
  frame: { type: String },
  audio: { type: String },
  link: { type: String },
  name: { type: String },
  dob: { type: String },
  email: { type: String },
  phone: { type: String },
  subscribe: { type: Boolean },
  isEdit: { type: Boolean },
  isMerge: { type: Boolean },
  hash: { type: String },
  onlinePath: { type: String },
  thumbnail: {
    path: { type: String },
    onlinePath: { type: String },
    hash: { type: String },
  },
  created: { type: Date, default: Date.now },
  updated: { type: Date, default: Date.now },
});

DataSchema.methods = {
  add: function (file, name, staticPath) {
    console.log("begin add in data model");
    this.original = name;
    this.effect = null;
    this.frame = null;
    this.audio = null;
    this.link = null;
    this.name = null;
    this.dob = null;
    this.email = null;
    this.phone = null;
    this.subscribe = false;
    this.isEdit = false;
    this.isMerge = false;
    this.onlinePath = staticPath
      ? url.format(
          file.path
            .replace(path.join(process.cwd(), "uploads"), staticPath)
            .replace("_", "")
        )
      : url.format(file.path).replace("_", "");
    this.thumbnail = null;
    this.hash = file.hash ? file.hash : null;
    this.created = Date.now();
    this.updated = Date.now();
    console.log("end add in data model");
    return this.save();
  },

  addThumbnail: function (file, staticPath) {
    this.thumbnail.path = url.format(file);
    this.thumbnail.onlinePath = url.format(
      file.replace(path.join(process.cwd(), "uploads"), staticPath)
    );
    this.thumbnail.hash = md5.sync(file);

    return this.save();
  },

  updateHash: function (file) {
    this.hash = md5.sync(file);

    return this.save();
  },
};

mongoose.model("Data", DataSchema);

