const mongoose  = require('mongoose');
const path      = require('path');
const url       = require('url');
const md5       = require('md5-file');
const fileUtils = require('../utils/fileUtils.js');

const FileSchema = new mongoose.Schema({
    file: {
        name: { type: String, unique: true },
        extension: { type: String },
        fullname: { type: String },
        path: { type: String },
        onlinePath: { type: String },
        hash: { type: String },
        thumbnail: {
            path: { type: String },
            onlinePath: { type: String },
            hash: { type: String }
        }
    },
    category: { type: String, required: true },
    created: { type: Date, default: Date.now },
    updated: { type: Date, default: Date.now },
    timestamp: { type: String }
});

FileSchema.methods = {

    addFile: function(file, category, staticPath) {
        this.file.name       = fileUtils.getName(file.name);
        this.file.extension  = fileUtils.getExtension(file.name);
        this.file.fullname   = file.name;
        this.file.path       = url.format(file.path);
        this.file.onlinePath = staticPath ? url.format(file.path.replace(path.join(process.cwd(), 'uploads'), staticPath)) : url.format(file.path);
        this.file.hash       = file.hash;
        this.file.thumbnail  = null,
        this.category        = category;
        this.timestamp       = Math.round(Date.now() / 1000);

        return this.save();
    },

    addThumbnail: function(file, staticPath) {
        this.file.thumbnail.path       = url.format(file);;
        this.file.thumbnail.onlinePath = url.format(file.replace(path.join(process.cwd(), 'uploads'), staticPath));
        this.file.thumbnail.hash       = md5.sync(file);

        return this.save();
    }
}

mongoose.model('File', FileSchema);

