const dataController = require("../controller/data.js");
const editvideos = [];

module.exports = function (io) {
  io.on("connection", function (socket) {
    console.log("client connected: " + socket.id);

    socket.on("disconnect", function () {
      console.log("user disconnected: " + socket.id);

      if (editvideos[socket.id] != null) {
        var videos = editvideos[socket.id];
        dataController.changeEditState(videos, false);
      } else {
        editvideos[socket.id] == null;
      }

      delete editvideos[socket.id];

      io.emit("flush-edit-video", { videos: [] });
    });

    socket.on("start", function (data) {
      console.log("received socket start video");
      io.emit("start-response", { message: "successfully start video" }); // response back to app mobile.
      io.emit("start", { data: null }); // send to app hardware.
    });

    socket.on("stop", function () {
      console.log("received socket stop video");
      io.emit("stop-response", { message: "successfully stop video" }); // response back to app mobile.
      io.emit("stop", { data: null }); // send to app hardware.
    });

    socket.on("edit-video", function (data) {
      const obj = JSON.parse(data);
      const arr = [];

      io.emit("notify-edit-video", {
        original: obj.original,
      });

      arr.push(obj.original);

      if (editvideos[socket.id] != null) {
        if (!editvideos[socket.id].includes(obj.original))
          editvideos[socket.id].push(obj.original);
      } else {
        editvideos[socket.id] = [];
        editvideos[socket.id].push(obj.original);
      }

      dataController.changeEditState(arr, true);
    });

    socket.on("release-video", function (data) {
      const obj = JSON.parse(data);
      const arr = [];

      io.emit("notify-release-video", {
        original: obj.original,
      });

      arr.push(obj.original);

      if (editvideos[socket.id] != null) {
        if (editvideos[socket.id].includes(obj.original)) {
          delete editvideos[socket.id][obj.original];
        }
      }

      dataController.changeEditState(arr, false);
    });

    socket.on("new-merged-video", function (data) {
      var obj = JSON.parse(data);
