const ffmpeg = require("fluent-ffmpeg");
const path = require("path");

const config = require("../../config.js");

ffmpeg.setFfmpegPath(path.join(config.workingDirectory, "ffmpeg.exe"));
ffmpeg.setFfprobePath(path.join(config.workingDirectory, "ffprobe.exe"));

module.exports.thumbnail = function (name, input, output, onsuccess, onfail) {
  ffmpeg(input)
    .on("error", (err, stdout, stderr) => onfail(err))
    .on("end", () => onsuccess(input))
    .inputOptions(["-vcodec libvpx"])
    .withOutputOptions(["-vcodec png", "-pix_fmt rgb32"])
    .thumbnail({
      count: 1,
      size: "1920x1080",
      filename: name,
      folder: output,
    });
};

