  ffmpeg(input)
    // .on('start', (command) => console.log('Spawned Ffmpeg with command: ' + command))  /* debug command */
    .on("error", (err, stdout, stderr) => {
      onfail(stderr); /*console.log(err + '-' + stdout + '-' + stderr)*/
