    // .complexFilter(['"[0:v]trim=0:3,setpts=PTS-STARTPTS[v1];[0:v]trim=3:4,setpts=8*(PTS-STARTPTS)[v2]"'])
    .complexFilter([
      "[0:v]trim=0:3,setpts=PTS-STARTPTS[v1];[0:v]trim=3:4,setpts=8*(PTS-STARTPTS)[v2];[0:v]trim=4:8,setpts=PTS-STARTPTS[v3];[0:v]trim=8:10,setpts=8*(PTS-STARTPTS)[v4];[0:a]atrim=0:2,asetpts=PTS-STARTPTS[a1];[0:a]atrim=2:5,asetpts=PTS-STARTPTS,atempo=0.5[a2];[0:a]atrim=5:8,asetpts=PTS-STARTPTS[a3];[0:a]atrim=8:10,asetpts=PTS-STARTPTS,atempo=0.5[a4];[v1][a1][v2][a2][v3][a3][v4][a4]concat=n=4:v=1:a=1",
    ])
